    if (hasErrors) {
        process.exitCode = 1;
    }
    if (results.length === 1) {
        const res = results[0];
        const detail = renderDetail('validation', {
            skill: res.name,
            status: res.valid ? 'valid' : 'invalid',
            schema: res.schemaVersion,
            version: res.version,
            states: res.stateCount,
            transitions: res.transitionCount,
