import path from 'node:path';
import fs from 'node:fs';
import { FSMEngine } from '@reactive-skills/runtime';
import { AxiError } from '../errors.js';
import { renderError, renderHelp, renderOutput, renderDetail } from '../toon.js';
import { getSuggestions } from '../suggestions.js';
import { extractJobFlag, resolveWorkspaceDir, resolveSkillPath } from '../args.js';
export async function stateCommand(args) {
    const { jobId, filteredArgs } = extractJobFlag(args);
    let skillName = filteredArgs[0];
    // If no skillName provided, check if current directory is a skill
    if (!skillName && fs.existsSync(path.join(process.cwd(), 'skill.yaml'))) {
        skillName = path.basename(process.cwd());
    }
    if (!skillName) {
        const error = new AxiError('Missing skill name', 'VALIDATION_ERROR', ['Usage: reactive-skills-axi state <skill-name> [--job <job-id>]', 'Example: reactive-skills-axi state my-skill']);
        return renderOutput([
            renderError(error.message, error.code, error.suggestions),
        ]);
    }
    try {
        const skillPath = resolveSkillPath(skillName);
        if (!skillPath) {
            const error = new AxiError(`Skill '${skillName}' not found in any known location`, 'NOT_FOUND', ['Checked: ./skills/, ~/.agents/skills/, ~/.gemini/config/skills/']);
            return renderOutput([renderError(error.message, error.code, error.suggestions)]);
        }
        const workspaceDir = resolveWorkspaceDir(skillPath);
        const engine = new FSMEngine({
            skillDir: skillPath,
            workspaceDir,
            jobId,
            autoRotateTerminal: true,
        });
        try {
            const currentState = engine.getCurrentState();
            const promptSlice = engine.generatePromptSlice();
            const events = engine.getEventStore().getAll();
            const latestEvent = events.length > 0 ? events[events.length - 1] : undefined;
            const effectiveJobId = (typeof engine.getJobId === 'function' ? engine.getJobId() : jobId) || 'default';
            const effectiveAlias = (typeof engine.getJobName === 'function' ? engine.getJobName() : undefined) || effectiveJobId;
            const lines = [];
            lines.push(renderDetail('state', {
                skill_id: skillName,
                current_state: currentState,
                event_id: latestEvent?.id || 'none',
                run_id: effectiveJobId,
            }, [
                { type: 'field', key: 'skill_id' },
                { type: 'field', key: 'current_state' },
                { type: 'field', key: 'event_id' },
                { type: 'field', key: 'run_id' },
            ]));
            lines.push(renderDetail('prompt', {
                raw_prompt: promptSlice.rawPrompt,
                allowed_tools: promptSlice.allowedTools.join(',') || 'none',
                exit_conditions: promptSlice.exitConditions.length,
            }, [
                { type: 'field', key: 'raw_prompt' },
                { type: 'field', key: 'allowed_tools' },
                { type: 'field', key: 'exit_conditions' },
            ]));
            const suggestions = getSuggestions({
                domain: 'state',
                action: 'get',
                skillName,
                jobId: effectiveAlias,
                currentState,
            });
            lines.push(renderHelp(suggestions));
            return renderOutput(lines);
        }
        finally {
            engine.close?.();
        }
    }
    catch (err) {
        const error = err instanceof AxiError
            ? err
            : new AxiError(err instanceof Error ? err.message : 'Failed to retrieve skill state', 'RUNTIME_ERROR', ['Check the skill name and ensure it exists in skills/ or global registry', 'Usage: reactive-skills-axi state <skill-name> [--job <job-id>]']);
        return renderOutput([
            renderError(error.message, error.code, error.suggestions),
        ]);
    }
}

/**
 * Utility to extract --job <id>, -j <id>, --run <id>, or REACTIVE_JOB_ID from CLI arguments
 */
export function extractJobFlag(args) {
    const filteredArgs = [];
    let jobId;
    let parentJobId;
    let idempotencyKey;
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (arg === '--job' || arg === '-j' || arg === '--run' || arg === '--run-id') {
            jobId = args[++i];
        }
        else if (arg === '--parent') {
            parentJobId = args[++i];
        }
        else if (arg === '--idempotency-key') {
            idempotencyKey = args[++i];
        }
        else if (arg.startsWith('--job=')) {
            jobId = arg.slice(6);
        }
        else if (arg.startsWith('--run=')) {
            jobId = arg.slice(6);
        }
        else if (arg.startsWith('--run-id=')) {
            jobId = arg.slice(9);
        }
        else if (arg.startsWith('--parent=')) {
            parentJobId = arg.slice('--parent='.length);
        }
        else if (arg.startsWith('--idempotency-key=')) {
            idempotencyKey = arg.slice('--idempotency-key='.length);
        }
        else {
            filteredArgs.push(arg);
        }
    }
    if (!jobId && process.env.REACTIVE_JOB_ID && process.env.REACTIVE_JOB_ID.trim()) {
        jobId = process.env.REACTIVE_JOB_ID.trim();
    }
    return { jobId, parentJobId, idempotencyKey, filteredArgs };
}
import path from 'node:path';
import os from 'node:os';
import fs from 'node:fs';
const HOME_DIR = os.homedir();
/**
 * Resolves a skill directory path from workspace or global agent registries.
 */
export function resolveSkillPath(skillName) {
    const candidates = [
        path.resolve(process.cwd(), 'skills', skillName),
        path.resolve(process.cwd(), 'skills', `_${skillName}_skill`),
        path.resolve(process.cwd(), skillName),
        path.resolve(HOME_DIR, '.agents', 'skills', skillName),
        path.resolve(HOME_DIR, '.gemini', 'config', 'skills', skillName),
        path.resolve(HOME_DIR, '.kilocode', 'skills', skillName),
        path.resolve(HOME_DIR, '.claude', 'skills', skillName),
    ];
    for (const candidate of candidates) {
        const yamlPath = path.join(candidate, 'skill.yaml');
        if (fs.existsSync(yamlPath)) {
            return candidate;
        }
    }
    return null;
}
/**
 * Resolves project workspace root given a skill directory path.
 * 1. If WORKSPACE_DIR environment variable is set, uses that.
 * 2. If skill is inside the current working directory, returns the workspace root containing the skill.
 * 3. If skill is outside cwd (e.g. global registry ~/.agents/skills or ~/.gemini/config/skills),
 *    returns process.cwd() as the execution workspace where deliverables and .reactive state belong.
 */
export function resolveWorkspaceDir(skillPath) {
    if (process.env.WORKSPACE_DIR) {
        return path.resolve(process.env.WORKSPACE_DIR);
    }
    const cwd = process.cwd();
    if (skillPath) {
        const resolvedSkill = path.resolve(skillPath);
        const rel = path.relative(cwd, resolvedSkill);
        const isInsideCwd = !rel.startsWith('..') && !path.isAbsolute(rel);
        if (isInsideCwd) {
            const parent = path.dirname(resolvedSkill);
            if (path.basename(parent) === 'skills') {
                return path.dirname(parent);
            }
            return cwd;
        }
    }
    return cwd;
}

